  const record = process.argv.includes('--record');
  const si = process.argv.indexOf('--seed');
  const seed = si > 0 ? Number(process.argv[si + 1]) : 1;
  fs.mkdirSync(out, { recursive: true });
  const g = await L.openGame({ seed });
  const fps = 30, dt = 1 / fps;
