  function state() { return race ? race.state : null; }

  function canPlay() {
    const s = state();
    return !!(s && renderer && !s.paused && s.mode === 'running' && !overlays.modalOpen());
  }

  function canPause(s) {
    if (!s || s.paused) return false;
    if (s.mode === 'countdown' || s.mode === 'running') return true;
